import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Weapon reach and spacing","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/combat/reach-and-spacing.md","filePath":"en/guide/combat/reach-and-spacing.md"}'),r={name:"en/guide/combat/reach-and-spacing.md"};function o(l,a,s,d,c,h){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="weapon-reach-and-spacing" tabindex="-1">Weapon reach and spacing <a class="header-anchor" href="#weapon-reach-and-spacing" aria-label="Permalink to &quot;Weapon reach and spacing&quot;">​</a></h1><p><strong>Status:</strong> Experimental three-weapon distances · Not implemented.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Reach belongs to the weapon/action; skill does not invisibly lengthen it.</li><li>The Experimental spear threatens farther away but loses effectiveness at close range.</li><li>Facing, line of sight and readable contact still matter; Lunge adds no automatic movement.</li></ul><p>Distance is part of melee combat. A spear can threaten farther away, while its close handling leaves room for a shorter weapon.</p><h2 id="at-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#at-a-glance" aria-label="Permalink to &quot;At a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Weapon/action</th><th>Maximum</th><th>Best range / trade-off</th></tr></thead><tbody><tr><td>Longsword</td><td>1 tile</td><td>Reliable close control</td></tr><tr><td>Spear Basic Thrust</td><td>2 tiles</td><td>Best at 2; disadvantaged at 1</td></tr><tr><td>Spear Lunge</td><td>3 tiles</td><td>Best at 2–3; costly commitment</td></tr><tr><td>War Hammer basic</td><td>1 tile</td><td>Close impact, slow recovery</td></tr><tr><td>Crushing Arc</td><td>2 tiles</td><td>Wide visible action; at most 2 hostiles</td></tr><tr><td>Sweep</td><td>1 tile</td><td>Short arc; at most 2 hostiles</td></tr></tbody></table><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li>Test distances use a grid; line of sight and facing still matter.</li><li>Spear thrusts and Brace counter at 1 tile take −10 percentage points accuracy and ×0.85 damage index.</li><li>Reach is a physical action property. Skill does not invisibly lengthen a weapon.</li><li>Lunge extends the strike; this test includes no automatic forward movement.</li><li>Visible reach must match mechanical reach before an action can be implemented.</li></ul><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><p>Step inside a spear&#39;s preferred distance to pressure its handling, or step out while its wielder commits to a Lunge. Neither tactic guarantees a hit.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/weapons-and-damage.html">Weapons</a> · <a href="/Syrolands-Public/en/guide/combat/numeric-prototype.html">Action tables</a> · <a href="/Syrolands-Public/en/game-design/combat/reach-and-spacing.html">Full design</a></p>',13)])])}const u=e(r,[["render",o]]);export{m as __pageData,u as default};
